import re
lines = open('scripts/db.py').readlines()
# find dispatch block starts
starts = []
for i, line in enumerate(lines, 1):
    m = re.search(r'args\.command (?:==|in)\s*\(?\s*"([^"]+)"', line)
    if m:
        starts.append((i, m.group(1)))
starts.append((len(lines)+1, "__END__"))
# find all INSERT/UPDATE occurrences including OR IGNORE/OR REPLACE
writes = []
for i, line in enumerate(lines, 1):
    m = re.search(r'\b(INSERT(?: OR \w+)? INTO|UPDATE)\s+"?([A-Za-z_]+)"?', line)
    if m:
        writes.append((i, m.group(1), m.group(2)))

# assign each write to enclosing block
import bisect
start_lines = [s[0] for s in starts]
blockmap = {}
for wi, verb, tbl in writes:
    idx = bisect.bisect_right(start_lines, wi) - 1
    if idx < 0: 
        cmdname = "__BEFORE_DISPATCH__"
    else:
        cmdname = starts[idx][1]
    blockmap.setdefault(cmdname, set()).add(tbl)

for cmd in sorted(blockmap):
    print(cmd, "->", sorted(blockmap[cmd]))
EOF

